"""Build explicitly versioned physical task profiles; no hardware access."""
import json,itertools
from pathlib import Path
ROOT=Path(__file__).resolve().parent
SOURCE='https://knowing-wandflower-7a9.notion.site/Task-Design-3e603e88cc6d81fcae8ae3167324b380'
OUT=ROOT/'act-config/tasks'
RESET=' Record matched initial layout and neutral poses for both arms. Confirm ACT start pose, all three camera views, open empty grippers and station stop control. Reset to the identical scene between policies. '
FINAL=' Every qualifying object must be released, settled for 2 seconds and unsupported by a gripper. Full success also requires both arms at the recorded origin.'
TASKS={}
def add(name,instruction,inventory,levels,criteria,phases,variant='se3-physical',note=''):
 assert len(criteria)==len(levels)-1 and len(phases)==len(levels)-1
 d={'name':name,'instruction':instruction+' Return both arms to origin.','reset_instruction':inventory+RESET+note,'success_question':criteria[-1]+FINAL,'rubric':{'version':'se3-interval-v1','source':('https://robodojo-benchmark.com/doc/sim-tasks/'+name+'/' if variant=='local-supplemental' else SOURCE),'variant':variant,'comparable_to_robodojo':False,'milestones':[{'points':0,'criterion':'No qualifying milestone reached.'}]+[{'points':p,'criterion':c} for p,c in zip(levels[1:],criteria)],'intervals':[{'phases':x} for x in phases]}}
 TASKS[name]=d
 (OUT/(name+'.json')).write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
def sequential(n,acquire,transport,place):
 return [[acquire.format(i=i),transport.format(i=i),place.format(i=i)+(' Verify all completed units and return both arms to origin.' if i==n else ' Preserve earlier qualifying units.')] for i in range(1,n+1)]
add('pack-objects-into-box','Place the car, shoe, toothbrush and hammer fully inside the open box, pointing the car nose, shoe toe, toothbrush head and hammer striking face left.', 'Orange toy car, red shoe, blue electric toothbrush, claw hammer, open cardboard box. Trace the initial box footprint and record front-left reference.',[0,10,25,50,100],[f'{i} objects fully inside, front-left, settled; box stays within initial footprint and grippers open.'+(' All four correct and arms at origin.' if i==4 else '') for i in range(1,5)],sequential(4,'Did the robot grasp and retain object {i} clear of the table?','Did it carry object {i} above the box and establish the defined front-left orientation?','Did it release object {i} fully inside and settled, with the box aligned and gripper open?'))
add('hang-mugs','Hang both mugs by their handles on separate pegs of the wooden mug tree.', 'Two ceramic mugs and upright wooden mug tree. Start mugs on table; base/table support does not count as hanging.',[0,40,100],['One mug securely hung, gripper open and rack upright.','Both mugs securely hung on separate pegs, rack upright and arms at origin.'],sequential(2,'Did it grasp and retain mug {i} without tipping or dropping it?','Did it carry mug {i} and align its handle with a different free peg?','Did it hang and release mug {i}, withdraw and leave the rack upright?'),'se3-adapted-two-mugs','Quality uses adapted intervals 0->40->100 with the same 30/30/40 phase rule; not the three-mug rubric.')
add('cover-blocks','Cover all three blocks from left to right and remember their colors. Then uncover green, light blue and dark blue in that order, keeping the cups upright.', 'Green, light-blue, dark-blue blocks; three identical yellow opaque cups. Balance all six block-position permutations across matched pairs; record color positions before covering without exposing that record to policy.',[0,5,15,30,100],['All three blocks hidden by upright cups, covered in left-to-right order.','After valid covering, green uncovered first; both blue blocks remain covered.','Green then light blue uncovered; dark blue remains covered.','Valid covering followed by green/light-blue/dark-blue reveal order, upright cups, arms at origin.'],[['Did it acquire the cups in left-to-right action order without disturbing blocks?','Did it transport each cup over its corresponding block?','Did it hide all blocks under upright cups while retaining their color positions?']]+[[f'Did it select the cup hiding {c} from memory?',f'Did it lift and park that cup upright without exposing a later target?',f'Did it reveal {c} in the required order while preserving remaining covers?'+(' Verify full order and return arms to origin.' if c=='dark blue' else '')] for c in ('green','light blue','dark blue')])
add('press-by-number','Press left green count button nine times, right dark-blue confirm once, middle cyan count button once, then right dark-blue confirm once again. No extra, missing or out-of-order presses.', 'Cards 9 and 1 over left green and middle cyan buttons; right dark-blue confirm. Record each activation with switch signal or clear full press/release video.',[0,100],['Exact left x9 / confirm / middle x1 / confirm sequence without extra/missed/premature presses, arms at origin.'],[['Did it bind card 9 to left, card 1 to middle and plan two confirmations?','Did it execute left x9, right confirm, middle x1, right confirm in that order?','Were all counts exact without extra/missed/out-of-order presses, then both arms returned to origin?']])
add('plug-in-charger','Insert the white USB adapter fully and upright into the marked outlet of the disconnected power strip.', 'White USB wall adapter and disconnected de-energized power strip; mark one outlet, trace allowed strip footprint, route cord clear. Record reference flush seating before rollout.',[0,100],['Adapter flush in marked outlet, no prong exposure beyond normal reference fit, upright, strip in bounds, gripper released and arms at origin.'],[['Did it grasp and retain adapter without unsafe prong contact?','Did it transport to marked outlet and align both prongs for insertion?','Did it fully seat and release adapter, leave strip in bounds and return both arms to origin?']])
add('insert-tubes','Insert both capped tubes one by one into the two marked wells of the orange rack, upright to the marked depth.', 'Two capped specimen tubes, orange rack with two marked wells and depth witness marks. Begin both tubes outside rack. Trace rack footprint and record fully seated reference.',[0,50,100],['One tube upright at marked depth in a marked well, gripper open.','Both tubes upright to depth in separate marked wells, rack in footprint and arms at origin.'],sequential(2,'Did it grasp and retain tube {i}?','Did it carry tube {i} above its unused marked well and align vertically?','Did it insert tube {i} to marked depth, release and leave it upright?'),'se3-adapted-two-tubes','Quality is adapted to 0->50->100; not the three-tube rubric.')
for language in (False,True):
 name='classify-objects-by-language' if language else 'classify-objects'
 inv=('Three toy peppers (red/green/yellow), two figurines, three watches (red-band/yellow-band/black-band); left blue, middle red, right yellow bins.' if language else 'Writing tools: black pen and white stylus. Toy vehicle: wooden race car. Camera equipment: action camera and two black mounts. Red, blue and green bins. All six objects begin outside bins.')
 instr=('Put all toy peppers into the left blue bin, all figurines into the middle red bin, and all watches into the right yellow bin.' if language else 'Sort writing tools, toy vehicle and camera equipment into three bins, one complete category per bin. Any category may use any bin; do not mix categories.')
 levels=[0,10,40,100] if language else [0,15,40,100]
 add(name,instr,inv,levels,[f'{i} complete categories, each in '+('its instructed bin' if language else 'a distinct bin')+', with every category member inside, no foreign objects and grippers open.'+(' All objects settled and arms at origin.' if i==3 else '') for i in range(1,4)],sequential(3,'Did it identify and acquire every member of category {i}'+(' using the instructed mapping?' if language else '?'),'Did it carry all objects of category {i} over '+('the instructed bin?' if language else 'the same chosen unused bin?'),'Did it release all category {i} members fully inside, verify completeness and no contamination?'))
add('play-stacking-toy','Place every piece onto its matching peg: purple circle, blue triangle, green square, orange square and red square. Complete all five groups.', 'Five-peg toy with 15 pieces: 1 purple circle, 2 blue triangles, 3 green squares, 4 orange squares, 5 red squares. Remove every piece before rollout and scatter without hiding peg base.',[0,10,25,45,70,100],[f'{i} entire matching peg groups completed, all pieces seated on base/stack and released.'+(' All five complete, arms at origin.' if i==5 else '') for i in range(1,6)],sequential(5,'Did it identify and retain every piece of scored group {i}?','Did it transport each piece of group {i} above the correct peg and align its hole?','Did it seat and release every piece to complete group {i}?'),'se3-extended-five-groups','Quality expands to five intervals 0/10/25/45/70/100, each 30/30/40; not the four-group original.')
add('align-blocks','Without picking up any cube, use the metal ruler to push the three purple cubes into one straight aligned row.', 'Three purple cubes and metal ruler. Fix top/side camera geometry, ruler parking position and initial cube poses. Record calibrated collinearity, yaw and no-lift measurements over the entire trajectory.',[0,100],['Cube centers collinear within frozen tolerance, faces parallel within yaw tolerance, no-lift limit respected throughout, ruler used, arms at origin.'],[['Did it grasp and position the ruler edge for pushing without lifting cubes?','Did it push all cubes toward a common line with the ruler while respecting the no-lift limit?','Did it meet collinearity/yaw tolerances, withdraw without disturbance and return arms to origin?']])
# The earlier 13-task list contains three extra tasks absent from the physical proposal.
# Retain them as explicit supplemental profiles; never describe them as Notion tasks.
for name,inv,ins in [('stack-bowls','Three nestable bowls.','Stack three bowls upright and stably.'),('stack-blocks','Three differently textured blocks.','Stack three blocks into one stable tower.')]:
 add(name,ins,inv,[0,15,100],['Two objects stably stacked, gripper open.','All three in one stable stack, released and arms at origin.'],sequential(2,'Did it acquire the next object for stacking step {i}?','Did it transport and align the retained object above its supporting object?','Did it release a stable upright stack without disturbing its support?'),'local-supplemental','Not in the ten-task Notion proposal. Quality is a declared local adaptation.')
add('arrange-largest-number','Arrange the four digit tiles 2, 4, 7, 9 on the four pads from left to right as the largest possible number, upright.', 'Four tiles 2,4,7,9 and four ordered pads. Target 9742; start all tiles off pads; freeze upright yaw reference.',[0,5,15,30,100],[f'{i} tiles in correct descending-order pads and upright, released.'+(' All four form 9742 and arms at origin.' if i==4 else '') for i in range(1,5)],sequential(4,'Did it select and retain the correct digit for placement {i}?','Did it transport the digit above its correct pad with upright orientation?','Did it release the correct digit on its pad with valid orientation?'),'local-supplemental','Not in the ten-task Notion proposal; four-digit variant fixed. Quality is a declared local adaptation.')
# Build six balanced assignment profiles, preserving distinct manifest identities.
extra=ROOT/'act-config/language-permutations';extra.mkdir(exist_ok=True)
for i,perm in enumerate(itertools.permutations(('toy peppers','figurines','watches'))):
 d=json.loads(json.dumps(TASKS['classify-objects-by-language']))
 d['instruction']=f'Put all {perm[0]} into the left blue bin, all {perm[1]} into the middle red bin, and all {perm[2]} into the right yellow bin. Return both arms to origin.'
 d['reset_instruction']+=f' Assignment {i+1}: '+d['instruction']
 (extra/f'{i+1}.json').write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
print('Built 13 full-rubric profiles and six language permutations; preserved four precision profiles.')
